#include <iostream>
#include <string>
#include <vector>
#include <ranges>
#include <algorithm>

int main() {
    using namespace std;
    string S, T;
    cin >> S >> T;

    vector<unsigned> dp(size(T) + 1);

    unsigned long ans = 0;
    for (const auto s : S) { // S の各文字 s を順に見て
        ++dp.front();
        for (const auto i : views::enumerate(T) | views::filter([s](const auto& t){return s == get<1>(t);}) | views::reverse | views::keys) { // s = T[i] となる i について降順に
            dp[i + 1] += dp[i]; // dp テーブルを更新する
            dp[i] = 0;
        }
        ans += ranges::fold_left(dp | views::take(size(T)), 0UL, plus{}); // 答えに dp テーブルの合計を足す
    }
    cout << ans << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
using ll=long long;
#define pb push_back
#define all(x) (x).begin(), (x).end()

int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    string s,t;
    cin>>s>>t;
    int N=s.size(),M=t.size();
    vector<vector<int>>idx(26);
    for(int i=0;i<N;i++){
        idx[s[i]-'a'].pb(i);
    }
    for(int i=0;i<26;i++)idx[i].pb(N);
    ll ans=0;
    for(int i=0;i<N;i++){
        int rig=i-1;
        for(int j=0;j<M;j++){
            rig=*upper_bound(all(idx[t[j]-'a']),rig);
            if(rig==N)break;
        }
        ans+=(rig-i);
    }
    cout<<ans<<"\n";
}
